from collections import deque
for _ in range(int(input())):
	(N, K) = list(map(int, input().split()))
	visited1 = [False] * N
	visited0 = [False] * N
	S = input()
	q0 = deque()
	q1 = deque()
	for i in range(N):
		if S[i] == '1':
			q1.append(i)
			visited1[i] = True
		else:
			q0.append(i)
			visited0[i] = True
	nrstones = [1] * N
	nrstzeroes = [1] * N
	if len(q0) == 0 or len(q1) == 0:
		print('0' * N)
		continue
	t = 0
	while q0:
		for i in range(len(q0)):
			x = q0.popleft()
			nrstzeroes[x] = t
			if x > 0 and visited0[x - 1] == False:
				q0.append(x - 1)
				visited0[x - 1] = True
			if x < N - 1 and visited0[x + 1] == False:
				q0.append(x + 1)
				visited0[x + 1] = True
		t += 1
	t = 0
	while q1:
		for i in range(len(q1)):
			x = q1.popleft()
			nrstones[x] = t
			if x > 0 and visited1[x - 1] == False:
				q1.append(x - 1)
				visited1[x - 1] = True
			if x < N - 1 and visited1[x + 1] == False:
				q1.append(x + 1)
				visited1[x + 1] = True
		t += 1
	s = ''
	for i in range(N):
		if S[i] == '1':
			if nrstzeroes[i] % 2 != K % 2 and K > nrstzeroes[i]:
				s += '1'
			else:
				s += '0'
		elif nrstones[i] % 2 == K % 2 and K >= nrstones[i]:
			s += '1'
		else:
			s += '0'
	print(s)
